# JavaScript/TypeScript Code Sample for MPT Payments

Based on the documentation provided, here's a complete sample synthesizing the key operations:

```javascript
import xrpl from 'xrpl'
import fs from 'fs'

const client = new xrpl.Client('wss://s.altnet.rippletest.net:51233')
await client.connect()

// Setup: Load or create accounts
const sender = xrpl.Wallet.fromSeed(senderSeed)
const { wallet: receiver } = await client.fundWallet()
const mptIssuanceID = 'your-mpt-issuance-id'

console.log(`Sender: ${sender.address}`)
console.log(`Receiver: ${receiver.address}`)

// Step 1: Authorize receiver to hold the MPT
const authorizeTx = {
  TransactionType: 'MPTokenAuthorize',
  Account: receiver.address,
  MPTokenIssuanceID: mptIssuanceID
}

xrpl.validate(authorizeTx)
const authorizeResponse = await client.submitAndWait(authorizeTx, {
  wallet: receiver,
  autofill: true
})

if (authorizeResponse.result.meta.TransactionResult !== 'tesSUCCESS') {
  throw new Error(`Authorization failed: ${authorizeResponse.result.meta.TransactionResult}`)
}
console.log('Receiver authorized!')

// Step 2: Check MPT balance via ledger_entry
async function getMPTBalance(address, mptIssuanceID) {
  try {
    const response = await client.request({
      command: 'ledger_entry',
      ledger_index: 'validated',
      mptoken: {
        mpt_issuance_id: mptIssuanceID,
        account: address
      }
    })
    return response.result.node?.MPTAmount ?? '0'
  } catch (e) {
    if (e.data?.error === 'entryNotFound') {
      return '0'
    }
    throw e
  }
}

const senderBefore = await getMPTBalance(sender.address, mptIssuanceID)
const receiverBefore = await getMPTBalance(receiver.address, mptIssuanceID)
console.log(`Sender balance: ${senderBefore}, Receiver: ${receiverBefore}`)

// Step 3: Send MPT payment
const paymentTx = {
  TransactionType: 'Payment',
  Account: sender.address,
  Destination: receiver.address,
  Amount: {
    mpt_issuance_id: mptIssuanceID,
    value: '100'
  }
}

xrpl.validate(paymentTx)
const paymentResponse = await client.submitAndWait(paymentTx, {
  wallet: sender,
  autofill: true
})

if (paymentResponse.result.meta.TransactionResult !== 'tesSUCCESS') {
